-- 2026-11-11: plain-language rewrite of the Japan koma text (every Japanese name says what it is).
update koma_shots set subtitle = $q$Smoky alleys, neon and station crowds, a few minutes' walk from the hotel.$q$, position_md = $q$Head to Shinjuku Station's west exit. Omoide Yokocho, a narrow alley of tiny yakitori grill bars, starts just north of it, beside the train tracks.$q$, look_md = $q$- Omoide Yokocho ("Memory Lane", the yakitori alley) from one end, the red lanterns stacking toward you — 35mm; wait for a cook in the grill smoke.
- The crowd crossing the big striped crosswalk outside the station, from above — ride the elevator across the street from the JR station; 85mm.
- One person standing still while the station crowd streams past — 35mm, about 1/8s, camera braced on a railing.
- People under the neon signs in the blocks between the station and the tracks — 35mm.$q$ where id = 98;
update koma_shots set position_md = $q$Umegaoka Station on the Odakyu line, then 5 minutes' walk. The plum trees are on the hill in the middle of the park.$q$, look_md = $q$- One branch of blossom against the sky — 85mm wide open so everything behind it melts.
- Someone photographing the plums on their phone: make them the subject — 85mm.
- The festival food stalls under the trees — 35mm.
- Red and white blossom on neighbouring trees, in one frame.$q$ where id = 113;
update koma_shots set subtitle = $q$A neighbourhood of low lanes, vintage clothes shops and cafés. Better for people than for views.$q$, position_md = $q$Out of Shimokitazawa Station and just wander. The lanes are small; you can't get lost for long.$q$, look_md = $q$- Clothes racks spilling out into a lane, one person browsing — 35mm around f/2.8.
- Someone sitting in a café window, shot from across the lane.
- The long footpath-park built on the old railway line beside the station, with people on it — stand at one end so the path leads in.
- Hand-painted signs and layers of stickers on the backs of shops — 85mm for the detail.$q$ where id = 99;
update koma_shots set subtitle = $q$A small canal lined with cherry trees (bare in February), little bridges and shops.$q$, position_md = $q$Out of Naka-Meguro Station and onto the canal path, either direction. Every bridge gives you a new view of the next one.$q$, look_md = $q$- The next bridge lined up behind this one — 85mm from the middle of a bridge pulls them together.
- Bare cherry branches over the water against the evening sky.
- Shop windows lighting up along the path at blue hour — 35mm.
- Someone crossing a bridge, shot from the next bridge along.$q$ where id = 100;
update koma_shots set subtitle = $q$Old-fashioned Tokyo: a small shopping street, a big cemetery and lanes of wooden houses.$q$, position_md = $q$Start at Yūyake Dandan ("sunset steps"), the short stone staircase at the top of the Yanaka Ginza shopping street, 5 minutes from Nippori Station.$q$, look_md = $q$- Looking down the sunset steps onto the shopping street as the sun drops.
- Shopkeepers and street cats on the shopping street — 85mm, from a step back.
- Rows of gravestones and bare trees in Yanaka Cemetery, one person walking — 35mm.
- Wooden houses and potted plants in the side lanes.$q$ where id = 101;
update koma_shots set position_md = $q$New York Bar, 52nd floor of the Park Hyatt (the bar from Lost in Translation). Ask for a window seat.$q$ where id = 114;
update koma_shots set subtitle = $q$An open-air museum: old thatched farmhouses moved here from all over Japan, on a wooded hill.$q$, position_md = $q$Follow the loop path up the hillside. You can walk into most of the houses.$q$, look_md = $q$- A thatched roof against the trees, shot from below on the path — 35mm.
- Smoke from an indoor fire pit lit by the window light, if a fire is going — 35mm; expose for the bright bits.
- Old tools, straw sandals and worn wood, close up — 85mm.
- The path between two houses with one person on it.$q$ where id = 115;
update koma_shots set subtitle = $q$A volcanic valley of steaming vents and yellow rock, with Mount Fuji behind on a clear day.$q$, position_md = $q$Get off the ropeway (cable car) at Owakudani Station and walk out to the viewing area above the steam vents.$q$, look_md = $q$- Ropeway cars crossing above the steam, small in the frame — 70-200.
- Mount Fuji over the ridge, if it's out — 70-200 makes it big.
- Someone peeling a black egg (boiled in the hot spring, sold at the shop) — 35mm.
- Yellow sulphur rock and steam vents up close.$q$ where id = 116;
update koma_shots set subtitle = $q$A red shrine gate standing in the lake, an avenue of giant cedars, and Fuji if it's clear.$q$, position_md = $q$The lake boat docks at Moto-Hakone. Walk the shore north (left as you get off) to Hakone Shrine, and come back along the cedar-lined road.$q$, look_md = $q$- The red gate in the water, from the boat as it comes in to dock — 70-200, with the shrine on the hill behind.
- People queueing to pose on the gate's steps, from along the shore — 70-200 on one couple.
- The avenue of huge cedar trees with one person for scale — 20-70, vertical.
- Mount Fuji over the lake, if it shows — best in the morning.$q$ where id = 102;
update koma_shots set subtitle = $q$Hakone Shrine's red gate (torii) standing in Lake Ashi.$q$, position_md = $q$On the lakeshore beside the red gate, looking out over the water. People queue on the gate's steps for photos; shoot from the side to leave them out.$q$ where id = 111;
update koma_shots set subtitle = $q$A mossy Edo-era stone road through the cedars, and a 400-year-old thatched tea house.$q$, position_md = $q$Get off the bus at the Amazake-chaya stop (named after the tea house) and walk a few minutes of the stone road either way.$q$, look_md = $q$- The stone road climbing into the trees, one person on it — 35mm; step back.
- Steam and wood smoke around the thatched tea house.
- Wet moss and paving stones close up — 85mm.$q$ where id = 103;
update koma_shots set subtitle = $q$The old canal quarter: willows, white-walled storehouses, lit up after dark.$q$, position_md = $q$Walk the canal from end to end, then the back streets once the day visitors have gone.$q$, look_md = $q$- The canal and willows from one of the stone bridges — 35mm; reflections at blue hour.
- The black-and-white tiled storehouse walls lit from the side — 85mm for the pattern.
- A canal tour boat from a bridge, the boatman in the frame (if the boats are running).
- The back streets after dark, lit by shop lanterns.$q$ where id = 104;
update koma_shots set subtitle = $q$Yayoi Kusama's yellow polka-dot pumpkin, on a little pier by Benesse House.$q$, position_md = $q$On the shore path facing the pier. People take turns posing; wait for a gap.$q$ where id = 112;
update koma_shots set subtitle = $q$The island's old fishing village: black wooden houses, with art installed inside some of them.$q$, position_md = $q$Leave the e-bikes near the Honmura port and walk. The lanes are only a few minutes across.$q$, look_md = $q$- Black charred-wood walls and a fabric door curtain, a cyclist passing — 35mm.
- Shadows across the lanes in low sun.
- The sea at the end of a lane.
- Small shrines and potted plants on doorsteps — 85mm.$q$ where id = 105;
update koma_shots set position_md = $q$Nakabashi, the stone bridge halfway along the canal, then walk the canal path both ways until 8:45.$q$, notes_md = $q$Bread from mugi (the bakery) first at 7:30, back to the hotel by 9:15.$q$ where id = 119;
update koma_shots set subtitle = $q$Yatai: tiny open-air food stalls along the river, glowing at night.$q$, position_md = $q$The stalls line the riverbank on the Nakasu side. The bridges at either end look along the whole row.$q$, look_md = $q$- One cook in the steam under the stall's light — 85mm wide open, tight.
- Faces through the stall's fabric curtain, the street dark behind.
- The row of stall lights along the river, from a bridge — 35mm.
- Neon reflected in the river from the bridge railing — rest the camera on it, about 1 second.$q$ where id = 106;
update koma_shots set subtitle = $q$Tonbai-bei: back-lane walls built from old kiln bricks and broken pottery.$q$, position_md = $q$The lanes run behind the old main street of porcelain shops (Uchiyama), a 10 to 15 minute loop off it.$q$, look_md = $q$- A brick wall running uphill, one person in the lane — 35mm.
- Bits of porcelain set into the clay — 85mm, close.
- Blue-and-white porcelain in the shop windows on the main street.
- An old kiln chimney above the roofs.$q$ where id = 117;
update koma_shots set subtitle = $q$About 15,000 lanterns over Chinatown and the river: the crowd shot of the trip.$q$, position_md = $q$Start in Chinatown, then Minato Park (the main festival square, with the giant lantern figures), then the river with the stone bridges.$q$, look_md = $q$- The ceiling of lanterns over a moving crowd — 35mm around 1/8s; the people blur, the lanterns stay sharp.
- One face lit by a giant lantern figure in Minato Park — 85mm.
- Lanterns over the river from a stone bridge, reflections at blue hour.
- The festival parade if you catch it — 85mm; follow one dancer.$q$ where id = 110;
update koma_shots set subtitle = $q$A big shrine famous for its plum trees, in bloom, with a busy shopping street leading up to it.$q$, position_md = $q$From Dazaifu Station walk up the shop-lined approach street, through the shrine, to the plum garden behind it.$q$, look_md = $q$- Plum blossom against the shrine's roof — 85mm wide open.
- Steam off the griddles making umegae-mochi (grilled rice cakes with red bean) on the approach street.
- Someone crossing the arched red bridges over the pond — 35mm.
- The Starbucks on the approach street, built from a lattice of wooden sticks (by Kengo Kuma) — 35mm, looking up.$q$ where id = 109;
update koma_shots set subtitle = $q$A big city-park pond crossed by island bridges; golden hour over the water.$q$, position_md = $q$Walk the path across the islands in the middle of the pond, then the shore on the sun's side.$q$, look_md = $q$- People on the island bridges as silhouettes against the low sun — 85mm.
- A jogger on the loop path, following them with the camera at 1/15s so they stay sharp and the background streaks.
- The swan pedal boats and the water after sunset.$q$ where id = 108;
update koma_shots set subtitle = $q$Quiet temples and a big shrine near the hotel, before the city wakes up.$q$, position_md = $q$Start at Kushida Shrine (Hakata's main shrine, next to the Ichiran ramen shop) and walk north through the temple blocks.$q$, look_md = $q$- Morning light through the shrine gate, one person bowing — 85mm.
- Temple walls and pine trees at Shōfuku-ji, Japan's first Zen temple — 35mm.
- The red five-storey pagoda at Tōchō-ji temple.
- Shopkeepers opening up in the Kawabata covered shopping arcade.$q$ where id = 107;
update koma_shots set subtitle = $q$The whole town, the channel and the shipyards from the hilltop temple park.$q$, position_md = $q$The viewing deck in Senkō-ji Park, at the top of the ropeway (cable car). Last car up is around 5:15, so be on it by then and walk down after. The 70-200 picks out rooftops, cranes and ferries; the 20-70 gets the whole view.$q$ where id = 83;
update koma_shots set subtitle = $q$The harbourfront promenade, the little ferry piers and the long covered shopping street.$q$, position_md = $q$The promenade runs east from Onomichi Station along the water. The covered shopping street (Hondōri) is one block inland, parallel to it.$q$, look_md = $q$- The lit ferry piers with the shipyard lights across the water — 35mm, camera rested on a mooring post.
- One of the small car ferries crossing with a single passenger — 85mm.
- Old signs and shop shutters in the covered shopping street.
- Cyclists rolling off the ferry.$q$ where id = 80;
update koma_shots set subtitle = $q$Stairways, temples and cats stacked up the hill above the water.$q$, position_md = $q$The lanes climb from behind the station side of town up to Senkō-ji temple. Go up early in the morning, or come down through them at dusk.$q$, look_md = $q$- Down a stairway with the water at the bottom of it — morning, before 10 (it's a holiday, so it fills up).
- Cats in Cat Alley (Neko no Hosomichi, a lane with painted lucky-cat stones), shot at cat height — 85mm wide open.
- Lanterns and the town below as you walk down from the temple at dusk — 35mm, braced on a wall.
- Laundry, plants and tiled roofs stacked down the hill — 85mm.$q$ where id = 84;
update koma_shots set notes_md = $q$After the castle, on your way back to catch the bus: buy a platform ticket (入場券, about ¥150) at the shinkansen ticket gates and go up to the platform. Around 11 the sun is behind your left shoulder, so the castle is lit from the front.$q$ where id = 118;
update koma_shots set subtitle = $q$Two islands framed by an old temple room's open window.$q$, position_md = $q$Inside Taichōrō, the guest hall of Fukuzen-ji temple on the harbour. The open window frames the two small islands offshore. It closes around 5, so go mid-afternoon.$q$ where id = 85;
update koma_shots set subtitle = $q$An old harbour of stone steps, a big stone lantern and lanes of warehouses.$q$, position_md = $q$Start at the big stone lantern on the harbour, work your way around the harbour, then into the lanes behind it.$q$, look_md = $q$- The stone harbour steps going down into the water — low afternoon light.
- The lanes of old warehouses behind the harbour, one person walking — 35mm.
- Fishing boats in the curve of the harbour.
- Fabric door curtains and old signs on the merchant houses.$q$ where id = 86;
update koma_shots set subtitle = $q$The harbour's big stone lantern (Jōyatō, an old lighthouse) at blue hour.$q$, position_md = $q$On the far side of the harbour from the stone lantern, so the lantern, the steps and their reflections line up. Brace on the harbour wall or use a small tripod. Check the last bus before you settle in.$q$ where id = 87;
update koma_shots set subtitle = $q$The hillside town at sunrise, from the island across the channel.$q$, position_md = $q$Take the small Fukumoto ferry from Tsuchidō Pier (east of the station) to Okajima Pier on Mukaishima island, 5 minutes. Shoot north back across the water at the town; the temple on the hill is almost straight ahead. The morning sun lights the hillside from the side.$q$ where id = 88;
update koma_shots set subtitle = $q$A street of old salt-merchant houses, with a temple balcony looking down on it.$q$, position_md = $q$Walk the main street of the old town (Hon-machi) end to end. The 70-200 can stay packed today.$q$, look_md = $q$- Old merchant houses along the main street, one person for scale.
- Wooden lattice windows and plaster walls up close — 20-70 at 70.
- A sake brewery front with its ball of cedar leaves over the door (it means new sake is ready).
- The steps up to Saihō-ji temple.$q$ where id = 89;
update koma_shots set subtitle = $q$The whole old town's tiled roofs from above.$q$, position_md = $q$The balcony of Fumeikaku, the wooden hall of Saihō-ji temple on the hill, looks straight down over the rooftops.$q$ where id = 90;
update koma_shots set subtitle = $q$Stone bridges over a still canal lined with storehouses.$q$, position_md = $q$The stone bridges over the middle stretch of Hachiman-bori, the town's old canal. Be there early while the water is flat and the boats are tied up. The 70-200 lines up storehouses and bridges; the 20-70 gets the reflection.$q$ where id = 92;
update koma_shots set subtitle = $q$An old stone-walled canal lined with white storehouses.$q$, position_md = $q$Walk the canal-side path between the bridges, then up Shinmachi-dōri, the street of old merchant houses.$q$, look_md = $q$- White storehouse walls along the canal path, lit from the side.
- Reflections in the still water, early before the boats move.
- A boat on the canal seen through the reeds — 70-200.
- The old merchant houses on Shinmachi-dōri.$q$ where id = 93;
update koma_shots set subtitle = $q$Kyoto's old sake-brewing district: breweries, a willow canal and sake bars.$q$, position_md = $q$Start at the Gekkeikan sake museum, walk the willow canal behind it, then up to the shopping street and the sake bars.$q$, look_md = $q$- Balls of cedar leaves and barrels over the brewery doors — 85mm.
- Your tasting set of sake cups on a bar counter — 85mm wide open.
- Willows and storehouse walls along the canal.
- Shopfronts on Ryōma-dōri, the old shopping street.$q$ where id = 95;
update koma_shots set subtitle = $q$The willow canal behind the old breweries as the lamps come on.$q$, position_md = $q$The canal path behind the Gekkeikan brewery buildings: wooden walls, willows and lamps coming on.$q$ where id = 94;
update koma_shots set subtitle = $q$Kyoto's river at night, with the lights along its banks.$q$, position_md = $q$On the north side of Shichijō bridge (5 minutes from the hotel), in the middle, looking up the river. Quieter than the next bridge up, which carries a main road.$q$ where id = 91;
update koma_shots set subtitle = $q$Stepping stones shaped like turtles where Kyoto's two rivers meet.$q$, position_md = $q$The stepping stones at the point where the Kamo and Takano rivers join, by Demachiyanagi Station. Wide for the stones and the river; the 70-200 for herons and the black kites (hawks). Keep food out of sight: the kites dive for it.$q$ where id = 96;
update koma_shots set subtitle = $q$The river junction at sunrise, then an old covered market street waking up.$q$, position_md = $q$Start at the stepping stones for sunrise, then cross to the Demachi Masugata covered shopping street as it opens.$q$, look_md = $q$- The covered market street as the shutters go up: bakeries, pickle shops, fish.
- People hopping across the turtle stepping stones.
- Herons and kites over the river — 70-200.
- The forest path to Shimogamo Shrine, just north of the rivers.$q$ where id = 97;
